import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Router, ActivatedRoute } from '@angular/router';
import { ActividadService } from '../../actividad/actividad.service';
import { OportunidadService } from '../oportunidad.service';

@Component({
  selector: 'app-oportunidad-actividades',
  standalone: true,
  imports: [CommonModule, RouterModule],
  templateUrl: './oportunidad-actividades.component.html',
  styleUrls: ['./oportunidad-actividades.component.css'],
})
export class OportunidadActividadesComponent implements OnInit {
  oportunidadId: number | null = null;
  oportunidad: any = null;
  actividades: any[] = [];
  loading = true;
  error = '';

  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private oportunidadService: OportunidadService,
    private actividadService: ActividadService,
  ) {}

  ngOnInit() {
    this.route.params.subscribe((params) => {
      this.oportunidadId = +params['id'];
      this.cargarOportunidad();
      this.cargarActividades();
    });
  }

  cargarOportunidad() {
    if (!this.oportunidadId) return;
    this.oportunidadService.obtenerPorId(this.oportunidadId).subscribe({
      next: (data) => (this.oportunidad = data),
      error: () => (this.error = 'Error al cargar oportunidad'),
    });
  }

  cargarActividades() {
    if (!this.oportunidadId) return;
    this.loading = true;
    this.actividadService.listarPorOportunidad(this.oportunidadId).subscribe({
      next: (data) => {
        this.actividades = data;
        this.loading = false;
      },
      error: () => {
        this.error = 'Error al cargar actividades';
        this.loading = false;
      },
    });
  }

  crearActividad() {
    if (this.oportunidadId) {
      this.router.navigate(['/actividades/nuevo'], {
        queryParams: { id_oportunidad: this.oportunidadId },
      });
    }
  }

  editar(id: number) {
    this.router.navigate(['/actividades', id, 'editar']);
  }

  eliminar(id: number) {
    if (confirm('¿Deseas eliminar esta actividad?')) {
      this.actividadService.eliminar(id).subscribe({
        next: () => this.cargarActividades(),
        error: () => (this.error = 'Error al eliminar actividad'),
      });
    }
  }

  volver() {
    this.router.navigate(['/oportunidades']);
  }
}
<div class="container">
  <div class="header">
    <div>
      <h2>Actividades - {{ oportunidad?.nombre_oportunidad }}</h2>
      <p class="subtitle">Oportunidad: {{ oportunidad?.numero_oportunidad }}</p>
    </div>
    <div class="header-actions">
      <button class="btn btn-primary" (click)="crearActividad()">+ Nueva Actividad</button>
      <button class="btn btn-secondary" (click)="volver()">Volver</button>
    </div>
  </div>

  <div *ngIf="error" class="alert alert-danger">{{ error }}</div>
  <div *ngIf="loading" class="loading">Cargando actividades...</div>

  <div *ngIf="!loading && actividades.length > 0" class="activities-list">
    <div *ngFor="let actividad of actividades" class="activity-card">
      <div class="activity-header">
        <h3>{{ actividad.asunto }}</h3>
        <span class="activity-date">{{ actividad.fecha_actividad | date: 'dd/MM/yyyy' }}</span>
      </div>
      <div class="activity-body">
        <div class="activity-row">
          <span class="label">Tipo:</span>
          <span class="value">{{ actividad.tipo_actividad }}</span>
        </div>
        <div class="activity-row">
          <span class="label">Prioridad:</span>
          <span class="value">{{ actividad.prioridad }}</span>
        </div>
        <div class="activity-row">
          <span class="label">Estado:</span>
          <span class="value">{{ actividad.estado_actividad }}</span>
        </div>
        <div class="activity-row">
          <span class="label">Cliente:</span>
          <span class="value">{{ actividad.cliente }}</span>
        </div>
        <div class="activity-row">
          <span class="label">Contacto:</span>
          <span class="value">{{ actividad.contacto }}</span>
        </div>
      </div>
      <div class="activity-actions">
        <button class="btn btn-sm btn-warning" (click)="editar(actividad.id_actividad!)">Editar</button>
        <button class="btn btn-sm btn-danger" (click)="eliminar(actividad.id_actividad!)">Eliminar</button>
      </div>
    </div>
  </div>

  <div *ngIf="!loading && actividades.length === 0" class="empty-state">
    <p>No hay actividades para esta oportunidad. <a (click)="crearActividad()">Crear una nueva</a></p>
  </div>
</div>
